/* NOVO no Letterbooks (não há equivalente no Letterboxd, que é
   servidor-primeiro e nunca precisa baixar um diário local).
   Uma linha de .linhas que anda enquanto você olha. Para voltar a uma lista
   parada, basta não pôr a classe .passo — o .linhas não muda em nada. */
.linhas .passo { color: var(--texto-3); }
.linhas .passo .glifo {
  flex: none; width: 16px; text-align: center;
  font-style: normal; color: var(--texto-3);
}
/* O número é o conteúdo desta tela, não informação de apoio: sobe de
   --texto-3 (3,9:1 sobre o fundo) para --texto-2 (8,6:1). */
.linhas .passo .valor { color: var(--texto-2); }
.linhas .passo.agora { color: var(--texto); }
.linhas .passo.agora .glifo { color: var(--texto-2); }
.linhas .passo.feito { color: var(--texto); }
/* verde = o que você fez. É o mesmo trabalho do ◉ de lido e do botão Salvar. */
.linhas .passo.feito .glifo { color: var(--a1); }

/* A tarja da fila existia no CSS desde o Sinc e nunca tinha sido usada por
   nenhuma tela. Esta é a primeira: é ela que diz que a conta tem diário
   esperando, ou que a rede caiu. Duas correções ao adotá-la:

   1) --texto-3 (#667788) sobre --superficie (#22282e) dá 3,2:1 — abaixo do
      4,5:1 que 13px exige. Sobe para --texto-2 (#99aabb), 6,2:1.
   2) ganha um link de ação à direita. Azul porque --a2 é a cor de link do
      sistema, e entra como TEXTO — não há --sobre-a2 para fazer fundo. */
.fila-aviso { color: var(--texto-2); }
.fila-aviso .glifo { flex: none; font-style: normal; color: var(--texto-3); }
.fila-aviso a {
  position: relative; margin-left: auto;
  color: var(--a2); font-weight: 600; white-space: nowrap;
}
.fila-aviso a:hover { color: var(--texto); }
/* Alvo de toque por inset, sem mexer no desenho. A tarja começa a 18px da
   borda e tem 12px de padding: a área para em 373px de 390, dentro da tela. */
.fila-aviso a::after { content: ""; position: absolute; inset: -13px; }

/* Texto só para leitor de tela. Até aqui isso existia soldado em
   .abas-pe a span; a tela de sincronização precisa de novo, então vira
   utilitário. Passo seguinte, fora deste item: .abas-pe a span passa a usar
   .oculto e a duplicata some. */
.oculto {
  position: absolute; width: 1px; height: 1px;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}

/* Não é componente novo: é o .botao com dois estados que nunca precisaram
   existir até aqui.

   Desabilitado, porque offline a sincronização não roda e um botão que não
   responde sem dizer por quê é pior que um botão apagado.

   44px de altura no celular, porque os 34px de hoje estão abaixo do alvo
   mínimo do próprio sistema. Aqui a caixa CRESCE, em vez de um pseudo com
   inset: .botao é caixa de verdade, então não vaza para fora da margem nem
   sobrepõe o vizinho — a folga de 9px do .linha-botoes continua bastando,
   porque as áreas de toque são as próprias caixas, não pseudos de 13px. */
.botao:disabled, .botao[aria-disabled="true"] { opacity: .5; cursor: default; }
.botao:disabled:hover { background: var(--superficie-2); color: var(--texto-2); }
@media (max-width: 720px) { .botao { min-height: 44px; } }

.avaliacoes-nota { margin: 0; color: var(--texto-2); font-size: 13px; line-height: 1.6; }
.avaliacoes-nota .mais { display: inline-block; margin-top: 10px; }
/* o botão de repetir é controle: cresce por inset, como manda a regra de alvo */
.avaliacoes-nota .mais { position: relative; }
.avaliacoes-nota .mais::after { content: ""; position: absolute; inset: -13px; }

.avaliacoes.esperando .avaliacoes-grafico,
.avaliacoes.esperando .avaliacoes-media {
  border-radius: var(--raio);
  background: linear-gradient(100deg, var(--superficie) 30%, var(--superficie-2) 50%, var(--superficie) 70%);
  background-size: 300% 100%;
  animation: brilho 1.1s linear infinite;
}
.avaliacoes.esperando .avaliacoes-grafico { height: 64px; }   /* 46 do histograma + 6 + 12 do eixo */
.avaliacoes.esperando .avaliacoes-media   { width: 52px; height: 34px; }
.avaliacoes.esperando .histograma,
.avaliacoes.esperando .histograma-eixo { visibility: hidden; }

/* NOVO — não existe no Letterboxd. Marca a sua nota dentro da distribuição da
   comunidade. Para voltar ao histograma puro do original, apague estas três
   regras e o terceiro item do .histograma-eixo. */
.histograma .col.minha { box-shadow: inset 0 -2px 0 var(--texto); }
.histograma-eixo .marca-minha { color: var(--texto-2); }
.histograma-eixo .marca-minha i {
  display: inline-block; width: 12px; height: 2px; margin-right: 5px;
  background: var(--texto); vertical-align: middle;
}

/* NOVO no Letterbooks: na ficha a resenha citada é o caminho para a página
   dela. No feed ela não é — lá a linha inteira já fala do livro, que tem alvo
   próprio. Para voltar ao comportamento do feed, troque o <a> por <p>. */
a.feed-resenha { display: block; color: var(--texto-2); }
a.feed-resenha:hover { background: var(--superficie-2); }

/* NOVO: .botao tem min-height 34px, abaixo dos 44 da regra de alvo. Aqui a
   área não pode crescer por ::after (inset −13 encostaria na .feed-acoes de
   cima, e a folga mínima entre alvos é 24px), então cresce como caixa.
   Caminho de volta: subir .botao para 44px e apagar esta classe. */
.botao.rede-mais { min-height: 44px; padding: 12px 18px; }

/* NOVO: a mesma tira da fila de envio, agora como "tentar de novo". Erro em
   seção secundária FALA (senão vira indistinguível de "ninguém leu ainda");
   vazio CALA (a seção some inteira, como já faz o trilho preguiçoso da home). */
button.fila-aviso { width: 100%; min-height: 44px; text-align: left; cursor: pointer; border: 0; }
button.fila-aviso:hover { background: var(--superficie-2); color: var(--texto-2); }

:root {
  /* Destrutivo e erro tinham virado laranja, e laranja já tem trabalho:
     é 'o que você gostou'. Na página da resenha isso ficava impossível de
     ler — o coração da curtida e o botão de apagar, na mesma cor, a 26px
     um do outro. Vermelho próprio, medido: 5,72:1 sobre --fundo.
     NOVO no Letterbooks. Para voltar atrás, aponte --perigo para var(--a3). */
  --perigo: #ff4d5e;
  --perigo-fraco: rgba(255, 77, 94, .12);
  --perigo-traco: rgba(255, 77, 94, .3);
}
[data-tema="cafe"] { --perigo: #ff6b5a; --perigo-fraco: rgba(255,107,90,.12); --perigo-traco: rgba(255,107,90,.3); }

.botao.perigo { background: none; color: var(--perigo); }
.botao.perigo:hover { background: var(--perigo-fraco); }
.linhas .perigo { color: var(--perigo); }
.comentario-apagar:hover { color: var(--perigo); }
.erro {
  padding: 13px 15px; border-radius: var(--raio);
  background: var(--perigo-fraco);
  box-shadow: inset 0 0 0 1px var(--perigo-traco);
  color: var(--perigo); font-size: 13px;
}

/* Os quatro style= que a V5 escreveu no lugar de classe, e o que cada um
   deveria ter sido. Nenhum deles entrou no CSS até hoje.

   js/app.js telaListas:
     style="margin-bottom:22px"                       → .listas-acao
     style="color:var(--texto-3);margin:0"            → .cartao-lista .vazia
     style="margin:10px 0 0;color:var(--texto-3);font-size:12px"
                                                      → .cartao-lista .contagem
       (e em 13px, não 12: 13 é o degrau de "meta, data, contagem";
        12 é o degrau de "legenda de capa")
   js/app.js desenhaLista:
     style="margin-top:28px"                          → .lista-botoes

   E as duas regras que faltam e que esta entrega deixou a descoberto: */

@media (max-width: 720px) {
  /* Prescrito na especificação do item 4 para TODO .botao; entrou só como
     .resenha-botoes .botao, escopado à tela da resenha. A V5 usa
     .linha-botoes cru em duas telas e herdou os 34px nas duas. */
  .botao { min-height: 44px; }
}

@media (max-width: 520px) {
  /* A irmã imersiva já faz isto (.resenha.sobre-heroi cai de -190 para -140).
     Sem esta linha, a 390px o cabeçalho da lista assenta aos 100px do herói,
     onde o degradê do .heroi::after cobre a capa com apenas ~0,38 de --fundo
     — a faixa mais clara de todo o degradê. */
  .lista-cabecalho.sobre-heroi { margin-top: -140px; }
}

/* O QUE ESTÁ NO ARQUIVO HOJE (css/app.css:277–278), e as cinco declarações
   que morrem: margin-top e margin-bottom perdem para .segmentos (css:974 e
   css:1119), o font-size do contêiner perde para .segmentos a (css:958), e o
   padding perde para .segmentos a (css:957).

   .segmentos-2 { margin-top: -8px; margin-bottom: 18px; font-size: 13px; }
   .segmentos-2 a { padding: 5px 12px; }

   O QUE TERIA SIDO ESCRITO: a variante DEPOIS do componente base, ganhando
   por ordem e não por sorte, e marcando subordinação por peso e superfície em
   vez de tamanho — a fita de baixo perde o trilho, e só a pílula ativa fica.
   Nenhum valor tipográfico novo: os dois já existem no sistema. */

/* (vai imediatamente depois do bloco .segmentos, css:974) */
.segmentos.segmentos-2 {
  margin-top: -10px;          /* encosta na fita de cima, sem colar */
  margin-bottom: 18px;
  background: none;           /* sem trilho: é recorte, não navegação */
  padding: 0;
}
.segmentos.segmentos-2 a { font-weight: 400; color: var(--texto-3); }
.segmentos.segmentos-2 a.ativa {
  background: var(--superficie-2); color: var(--texto); font-weight: 600;
}
/* O separador de css:963 é do trilho; sem trilho ele some junto. */
.segmentos.segmentos-2 a + a::before { display: none; }

@media (max-width: 720px) {
  /* o .segmentos genérico sangra -8px; a fita subordinada não sangra, porque
     sem trilho não há o que sangrar e a pílula ativa deve alinhar com o h1. */
  .segmentos.segmentos-2 { margin-left: 0; margin-right: 0; }
}

/* NOVO no Letterbooks: a marca de "tem coisa nova". Nenhum dos 24 quadros do
   inventário mostra ponto em ícone de aba — o desvio é assumido aqui.
   A cor é --texto e NÃO um acento, porque nenhum dos três acentos cabe:
   verde é "o que VOCÊ fez" (e isto é o que a outra pessoa fez), laranja é
   "o que você gostou" (e aqui é alguém gostando de você), azul é "onde você
   está" — ponto azul em aba inativa diria que ela é a aba ativa. A regra manda:
   estado que não cabe nos três NÃO ganha acento. Precedente no arquivo:
   .histograma .col.minha, que usa --texto pelo mesmo motivo.
   O anel é a própria cor da barra, para o ponto não encostar no ícone.
   Caminho de volta: apagar as três regras e o <span> que as usa. */
.marca-nova {
  flex: none; width: 8px; height: 8px; border-radius: 50%;
  background: var(--texto);
  box-shadow: 0 0 0 2px var(--fundo-2);
}
.abas-pe a { position: relative; }
.abas-pe .marca-nova { position: absolute; top: 10px; left: calc(50% + 7px); }

/* NOVO: a linha de notificação tem UM destino, então a linha inteira é o alvo
   — ao contrário da linha do feed, que carrega ♥ e 💬 dentro e por isso não
   pode ser link. Mora dentro de .resultados, que já é a sangria de ±18px das
   listas de borda a borda, e devolve o padding lateral como .resultado e
   .linhas fazem. Caminho de volta: trocar o <a> por <article> e apagar isto. */
a.feed-linha { padding-left: 18px; padding-right: 18px; }
a.feed-linha:active { background: var(--superficie); }
@media (min-width: 721px) {
  a.feed-linha { padding-left: 0; padding-right: 0; }
}

.botao:disabled { opacity: .5; cursor: default; }
.botao:disabled:hover { background: var(--superficie-2); color: var(--texto-2); }
.botao.perigo:disabled:hover { background: none; color: var(--perigo); }

/* NOVO — não existe no Letterboxd, que não pré-visualiza privacidade em
   nenhum quadro do mapa. O espelho mostra os componentes de verdade com os
   dados de verdade; o modificador só impede que ele funcione como página.
   Para tirar a pré-visualização, apague este bloco e a seção que o usa. */
.bloco.espelho { pointer-events: none; -webkit-user-select: none; user-select: none; }

.linhas .marca-escolha {
  width: 16px; flex: none; font-style: normal; color: var(--a1);
}
.linhas [role="radio"][aria-checked="false"] .marca-escolha { color: transparent; }

/* NOVO — nenhum dos 24 quadros do mapa mostra um caminho de denúncia, então
   isto não vem do original. É um .mais com o contraste consertado, o hover
   tirado do verde (verde é «o que voce fez», e denunciar nao e conquista) e a
   area de toque na regua de verdade. Para tirar a denuncia da tela, apague
   este bloco e a linha que o usa em desenhaResenha. */
.denunciar {
  display: inline-block; position: relative;
  margin-top: 22px; color: var(--texto-2);
}
.denunciar:hover { color: var(--texto); }
/* 11px x 1,5 = 16,5px de caixa. Com inset -13 daria 42,5 — a mesma conta que
   .estado-exposicao e .avaliacoes-nota .mais erram hoje, no ar. -14 da 44,5 e
   continua dentro dos 18px de margem da pagina. */
.denunciar::after { content: ""; position: absolute; inset: -14px; }

/* SUBSTITUI css:1440-1444. O terceiro lugar da linha do comentario e UM
   lugar com dois inquilinos que nunca aparecem juntos: o x de apagar, quando
   o comentario e seu, e a bandeira de denunciar, quando e de outra pessoa.
   Mesma geometria, mesma area de toque; muda so o hover, porque apagar faz
   sumir e denunciar nao. */
.comentario-apagar, .comentario-denunciar {
  background: none; border: 0; cursor: pointer; align-self: start;
  color: var(--texto-3); font-size: 18px; line-height: 1; padding: 2px 4px;
}
.comentario-apagar:hover    { color: var(--perigo); }
.comentario-denunciar:hover { color: var(--texto-2); }

/* E .comentario-denunciar entra nas DUAS listas de seletor do bloco de alvos
   de toque, ao lado de .comentario-apagar: em css:1468 (position: relative) e
   em css:1482 (o ::after com inset -13px). Nenhuma regra de crescimento nova:
   a caixa de ~22x19 com inset -13 ja da 48 x 45px. */

/* css:620 — o .mais dos estados de Avaliacoes («Tentar de novo», «Avaliar
   este livro», «Criar conta para avaliar»): 42,5px hoje. */
.avaliacoes-nota .mais::after { content: ""; position: absolute; inset: -14px; }

/* css:1515 — a marca de diario fechado no perfil: 42,5px hoje. */
.estado-exposicao::after { content: ""; position: absolute; inset: -14px; }

/* css:469 — e o .mais SEM crescimento nenhum, que e o pior dos tres: 16,5px
   nus em «Ler a sinopse inteira» (js/app.js:708), «Ler a biografia inteira»
   (js/app.js:2127) e «Limpar» das buscas recentes (js/app.js:2453). Cresce na
   raiz, e as regras acima viram redundancia benigna. */
.mais { position: relative; }
.mais::after { content: ""; position: absolute; inset: -14px; }
/* .recentes-topo .mais fica ao lado do rotulo «BUSCAS RECENTES», que nao e
   alvo: nao ha vizinho de toque para se sobrepor. */

componentesNovos:
FOLHA DE UMA PERGUNTA — .folha-fundo.com-campo + .folha-pergunta + .aviso-campo. UMA classe nova de estrutura e uma de conteúdo, e a razão de existirem é medida, não estética: .com-campo troca a âncora de center para flex-start, porque folha centrada com teclado aberto põe os botões debaixo do teclado (medição inteira na primeira tela). .folha-pergunta trava max-width em 350 e encurta a caixa longa para 72px. .aviso-campo é a linha reservada de validação/contagem. É montagem de peças existentes (.folha + .campo + .folha-rodape), não um componente novo — o sistema ganha um ARRANJO nomeado, não um sétimo padrão de lista.

CSS EXATO, ao fim do bloco «folha» de css/app.css:

/* ==================================== folha de uma pergunta ============== */
/* NOVO — não existe no Letterboxd, que é servidor-primeiro e cria lista em página
   inteira. Substitui os prompt() do navegador em nome de lista, renomear,
   descrição e meta do ano. Para voltar ao prompt, apague este bloco e o
   abrirFolhaCampo() de js/app.js.

   A classe muda UMA coisa: a âncora. .folha-fundo é `align-items: center`
   (css:1027) e é `position: fixed; inset: 0` — ou seja, medida contra o viewport
   de LAYOUT, que o teclado virtual NÃO encolhe (o padrão do Chrome é
   interactive-widget=resizes-visual; o iOS Safari desloca o visual e deixa o
   layout parado). Medido: iPhone 14 (390x844) com teclado pt-BR sobra ~398px no
   topo; iPhone SE (375x667) sobra ~293px. Uma folha de 279px CENTRADA em 844
   ocupa y=282..561: o campo fica pela metade e os dois botões ficam inteiros
   embaixo do teclado. Ancorar embaixo é pior — some tudo. O topo é a única
   faixa que o teclado nunca cobre. */
.folha-fundo.com-campo {
  align-items: flex-start;
  padding-top: calc(12px + env(safe-area-inset-top));
}

/* TETO DE ALTURA: 290px, abaixo dos 293 do aparelho mais estreito que o app
   atende. É ele que obriga esta folha a ter UMA pergunta — a segunda não caberia
   acima do teclado. Formulário de dois campos ou mais é ROTA (#/perfil/editar). */
.folha-pergunta { max-width: 350px; }

/* Os 120px de .campo textarea (css:1016) estouram o teto em 47px. 72px são ~3
   linhas de 1.6, que é o tamanho de uma descrição de lista deste app. */
.folha-pergunta textarea { min-height: 72px; }

/* A linha de validação e contagem fica SEMPRE reservada — visibility e não
   display — para o rodapé não subir e descer a cada tecla, com o dedo parado no
   teclado logo abaixo. 12px em --texto-2 e não --texto-3: esta frase é a razão de
   o botão estar travado, e --texto-3 dá 3,9:1 sobre o fundo. */
.aviso-campo {
  display: block; margin: 6px 0 0; min-height: 18px;
  font-size: 12px; line-height: 1.5; color: var(--texto-2);
}
.aviso-campo:empty { visibility: hidden; }
.aviso-campo.impede { color: var(--perigo); }

#/perfil/editar — ROTA nova, sem componente novo nenhum: reusa .conta (max-width 420, centrado), .campo, .conta-erro e .linha-botoes exatamente como #/conta já faz. O único CSS que ela pede é tirar um style inline que já está no ar e virar token de sistema, porque a regra «estado vem de token, não de string» proíbe o que existe hoje:

/* #/conta escrevia isto em style inline no app.js (js/app.js:3817). A bio é um
   campo curto nas duas telas de perfil, e agora são duas: vira regra. */
.campo textarea.curta { min-height: 70px; }

